export const IMPORT_BATCH_SIZE = 50;

// ── GAP-IMP-P1-02/P1-03: Batch resolve + validate

interface BatchResolveRow {
  rowIndex: number;
  supplierName?: string;
  bankAccount?: string;
  taxCode?: string;
}

interface BatchValidateRow {
  rowIndex: number;
  sourceRef?: string;
  accountCode?: string;
  transactionDate?: string;
}

interface BatchResolveResult {
  rowIndex: number;
  supplierId?: string;
  supplierCode?: string;
  supplierName?: string;
  confidence: number;
}

interface BatchValidateResult {
  rowIndex: number;
  valid: boolean;
  warnings?: string[];
  duplicateSourceRef?: boolean;
}

type BatchEnvelope<T> = {
  results?: T[];
  Results?: T[];
};

function pickBatchResults<T>(data: BatchEnvelope<T> | null | undefined): T[] {
  return data?.results ?? data?.Results ?? [];
}

/** GAP-IMP-P1-02: Resolve NCC theo batch — BankStatementImportController */
export async function resolveBatch(rows: BatchResolveRow[]): Promise<BatchResolveResult[]> {
  if (rows.length === 0) return [];
  try {
    const res = await apiClient.post<BffResponse<BatchEnvelope<BatchResolveResult>>>(
      `${BASE}/resolve-batch`,
      { rows },
    );
    const results = pickBatchResults(await unwrap(res));
    return results.map(r => ({
      rowIndex: Number((r as BatchResolveResult & { RowIndex?: number }).rowIndex
        ?? (r as BatchResolveResult & { RowIndex?: number }).RowIndex
        ?? 0),
      supplierId: (r as BatchResolveResult & { SupplierId?: string }).supplierId
        ?? (r as BatchResolveResult & { SupplierId?: string }).SupplierId,
      supplierCode: (r as BatchResolveResult & { SupplierCode?: string }).supplierCode
        ?? (r as BatchResolveResult & { SupplierCode?: string }).SupplierCode,
      supplierName: (r as BatchResolveResult & { SupplierName?: string }).supplierName
        ?? (r as BatchResolveResult & { SupplierName?: string }).SupplierName,
      confidence: Number(
        (r as BatchResolveResult & { Confidence?: number }).confidence
        ?? (r as BatchResolveResult & { Confidence?: number }).Confidence
        ?? 0,
      ),
    }));
  } catch {
    return rows.map(r => ({ rowIndex: r.rowIndex, confidence: 0 }));
  }
}

/** GAP-IMP-P1-03: Validate rows theo batch — BankStatementImportController */
export async function validateBatch(rows: BatchValidateRow[]): Promise<BatchValidateResult[]> {
  if (rows.length === 0) return [];
  try {
    const res = await apiClient.post<BffResponse<BatchEnvelope<BatchValidateResult>>>(
      `${BASE}/validate-batch`,
      { rows },
    );
    const results = pickBatchResults(await unwrap(res));
    return results.map(r => {
      const ext = r as BatchValidateResult & {
        RowIndex?: number;
        Valid?: boolean;
        Warnings?: string[];
        DuplicateSourceRef?: boolean;
      };
      return {
        rowIndex: Number(ext.rowIndex ?? ext.RowIndex ?? 0),
        valid: Boolean(ext.valid ?? ext.Valid ?? false),
        warnings: ext.warnings ?? ext.Warnings,
        duplicateSourceRef: Boolean(ext.duplicateSourceRef ?? ext.DuplicateSourceRef ?? false),
      };
    });
  } catch {
    // Soft-fail: không chặn wizard khi BE tạm offline
    return rows.map(r => ({ rowIndex: r.rowIndex, valid: true }));
  }
}

/** GAP-IMP-P2-06 / P1-01: Download template file — GET …/template */
export async function downloadTemplate(voucherKind: string): Promise<void> {
  const kind = (voucherKind || 'bao_no').trim();
  const blob = await apiClient.getBlob(`${BASE}/template?voucherKind=${encodeURIComponent(kind)}`);
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `mau-import-${kind}.xlsx`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}





