/**
 * Parse thanh toán lô — MB bulk + TCB Payroll.
 * SSOT: `{RevaDataRepo}/data/sao-ke-ngan-hang/Template/README.md` §B
 * · status = cột Trạng thái
 * · staffNote = cột «Lưu ý/Note» (Payroll) hoặc trailing sau last bank header col (MB col 9+)
 * · TB (MB): ô FT/ERROR = lý do lỗi — không gán ftNumber
 */
import * as XLSX from 'xlsx';
import type { BatchDetailLine } from '../services/kt/bankStatementImportModels';
import { formatBatchSourcePath, isBatchLineSuccess } from './batchPaymentStatus';

/** Strip dấu + lowercase — so sánh nhất quán NFC/NFD. */
export function normBulkText(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase();
}

export function parseBatchAmount(v: unknown): number {
  if (typeof v === 'number') return v;
  const s = String(v || '').trim().replace(/[^\d,.]/g, '');
  if (!s) return 0;
  if (s.includes(',') && !s.includes('.')) return parseFloat(s.replace(/,/g, '')) || 0;
  if (s.includes('.') && s.split('.').length > 2) return parseFloat(s.replace(/\./g, '')) || 0;
  return parseFloat(s.replace(/,/g, '')) || 0;
}

function looksLikeFt(raw: string): boolean {
  return /^ft\d+/i.test(String(raw || '').trim());
}

/** Meta header sheet: Ref No / Bank reference ID · Transaction / Value date. */
export function extractBatchSheetMeta(rows: unknown[][]): {
  transactionDate?: string;
  refNumber?: string;
} {
  let transactionDate: string | undefined;
  let refNumber: string | undefined;

  const valueFromRow = (cells: string[]): string | undefined => {
    for (const c of cells) {
      if (!c.includes(':')) continue;
      const m = c.match(/:\s*(.+)$/);
      if (m?.[1]?.trim()) return m[1].trim();
    }
    for (let j = 1; j < cells.length; j++) {
      if (cells[j]) return cells[j];
    }
    return undefined;
  };

  for (let i = 0; i < Math.min(rows.length, 22); i++) {
    const cells = ((rows[i] as unknown[]) || []).map(c => String(c ?? '').trim());
    if (!cells.some(Boolean)) continue;
    const joined = cells.join(' ');
    const lower = joined.toLowerCase();
    const norm = normBulkText(joined);

    if (cells.filter(Boolean).length >= 6) continue;

    if (!refNumber) {
      const isRef =
        lower.includes('ref no')
        || norm.includes('bank reference id')
        || norm.includes('bank reference')
        || (norm.includes('so but toan') && (norm.includes('bank reference') || lower.includes(':')))
        || (lower.includes('tham chiếu') && cells[0].includes(':'));
      if (isRef) {
        const v = valueFromRow(cells);
        if (v && !/transaction reference|so tham chieu/i.test(normBulkText(v))) {
          refNumber = v;
        }
      }
    }

    if (!transactionDate || norm.includes('value date') || norm.includes('ngay thanh toan')) {
      const isDate =
        lower.includes('transaction date')
        || lower.includes('ngày giao dịch')
        || norm.includes('value date')
        || norm.includes('ngay thanh toan')
        || ((norm.includes('initiate date') || norm.includes('ngay khoi tao')) && !transactionDate);
      if (isDate) {
        const preferValue =
          norm.includes('value date')
          || norm.includes('ngay thanh toan')
          || lower.includes('transaction date')
          || lower.includes('ngày giao dịch');
        const v = valueFromRow(cells);
        if (v && (preferValue || !transactionDate)) {
          transactionDate = v;
        }
      }
    }
  }
  return { transactionDate, refNumber };
}

/**
 * Parse 1 sheet → dòng batch (MB bulk + TCB Payroll).
 * Trả [] nếu không nhận dạng header.
 */
export function parseBatchSheet(
  rawRows: unknown[][],
  meta: { transactionDate?: string; refNumber?: string },
  lineOffset = 0,
  sourceFilePath?: string,
  sheetTabName = 'csv',
): BatchDetailLine[] {
  let headerRowIndex = -1;
  let bestScore = 0;
  for (let i = 0; i < Math.min(rawRows.length, 35); i++) {
    const rowText = ((rawRows[i] as string[]) || []).map(c => String(c)).join(' ').toLowerCase().replace(/\r?\n/g, ' ');
    const norm = normBulkText(rowText);
    let score = 0;
    if (
      rowText.includes('th\u1ee5 h\u01b0\u1edfng')
      || rowText.includes('beneficiary')
      || norm.includes('credit account name')
      || norm.includes('nguoi thu huong')
      || norm.includes('ten don vi thu huong')
    ) {
      score += 3;
    }
    if (rowText.includes('s\u1ed1 ti\u1ec1n') || rowText.includes('amount') || norm.includes('so tien')) score += 2;
    if (rowText.includes('t\u00e0i kho\u1ea3n') || rowText.includes('account') || norm.includes('tai khoan')) score += 2;
    if (rowText.includes('ng\u00e2n h\u00e0ng') || rowText.includes('bank') || norm.includes('ngan hang')) score += 1;
    if (
      rowText.includes('chi ti\u1ebft')
      || rowText.includes('n\u1ed9i dung')
      || rowText.includes('payment')
      || norm.includes('dien giai')
      || rowText.includes('description')
    ) {
      score += 1;
    }
    if (norm.includes('ft id') || norm.includes('payroll') || norm.includes('transaction status') || norm.includes('trang thai')) {
      score += 1;
    }
    if (score > bestScore) {
      bestScore = score;
      headerRowIndex = i;
    }
  }
  if (headerRowIndex === -1 || bestScore < 4) return [];

  const headers = ((rawRows[headerRowIndex] as string[]) || [])
    .map(h => String(h).trim().toLowerCase().replace(/\r?\n/g, ' '));
  const headersNorm = headers.map(h => normBulkText(h));

  const ci = (...kws: string[]) => {
    for (const kw of kws) {
      const kwNorm = normBulkText(kw);
      const idx = headersNorm.findIndex(h => h.includes(kwNorm));
      if (idx >= 0) return idx;
    }
    return -1;
  };

  const sttIdx = ci('stt', '(no.)', 'so thu tu', 'số thứ tự');
  const accIdx = ci(
    'tài khoản hưởng', 'credit account', 'số tài khoản thụ hưởng',
    'số tài khoản', 'account no', 'stk', 'số tk', 'tài khoản',
    'account',
  );
  const nameIdx = ci(
    'người thụ hưởng', 'credit account name', 'tên đơn vị thụ hưởng', 'thụ hưởng',
    'beneficiary name', 'beneficiary',
  );
  const bankIdx = ci(
    'tên ngân hàng hưởng', 'beneficiary bank', 'ngân hàng thụ hưởng', 'ngân hàng hưởng',
    'ngân hàng', 'bank',
  );
  const amtIdx = ci('số tiền giao dịch', 'số tiền', 'amount', 'tiền');
  const descIdx = ci(
    'chi tiết thanh toán', 'payment details', 'payment detail', 'nội dung chuyển',
    'diễn giải', 'description', 'nội dung', 'content',
  );
  const feeIdx = ci('phí', 'fee', 'charge');
  const statusIdx = ci('trạng thái giao dịch', 'transaction status', 'trạng thái', 'status', 'kết quả');
  const ftIdx = ci(
    'ft id', 'ft number', 'bút toán', 'số bút toán', 'mã giao dịch', 'số ft', 'ft2', 'transaction id', 'lý do',
  );
  const noteHeaderIdx = ci('lưu ý', 'note', 'ghi chú', 'staff note');
  const bankCodeIdx = ci('mã nh', 'bank code');
  const txnRefIdx = ci('transaction reference', 'số tham chiếu');
  const debitAccIdx = ci('debit account', 'tài khoản nguồn');

  const guessedFtIdx = ftIdx >= 0 ? ftIdx : headers.findIndex((_, col) => {
    const vals = (rawRows.slice(headerRowIndex + 1, headerRowIndex + 5) as string[][])
      .map(r => String(r?.[col] ?? ''));
    return vals.some(v => looksLikeFt(v));
  });

  const bankSystemIdx = [
    sttIdx, accIdx, nameIdx, bankIdx, amtIdx, descIdx, feeIdx,
    statusIdx, guessedFtIdx, noteHeaderIdx, bankCodeIdx, txnRefIdx, debitAccIdx,
  ].filter(i => i >= 0);

  // Last named NH col (header text non-empty + system) — MB ends at FT/ERROR (8)
  let lastBankHeaderCol = bankSystemIdx.length ? Math.max(...bankSystemIdx) : -1;
  for (let i = 0; i < headers.length; i++) {
    if (!headersNorm[i]) continue;
    const h = headersNorm[i];
    const isSystem =
      h.includes('stt')
      || h.includes('account')
      || h.includes('tai khoan')
      || h.includes('beneficiary')
      || h.includes('thu huong')
      || h.includes('amount')
      || h.includes('so tien')
      || h.includes('bank')
      || h.includes('ngan hang')
      || h.includes('payment')
      || h.includes('chi tiet')
      || h.includes('dien giai')
      || h.includes('description')
      || h.includes('phi')
      || h.includes('fee')
      || h.includes('charge')
      || h.includes('status')
      || h.includes('trang thai')
      || h.includes('ft')
      || h.includes('but toan')
      || h.includes('ly do')
      || h.includes('luu y')
      || h.includes('note')
      || h.includes('ghi chu')
      || h.includes('debit')
      || h.includes('credit')
      || h.includes('tham chieu');
    if (isSystem && i > lastBankHeaderCol) lastBankHeaderCol = i;
  }

  const dataSample = rawRows.slice(headerRowIndex + 1, headerRowIndex + 40) as unknown[][];
  const maxCols = Math.max(
    headers.length,
    lastBankHeaderCol + 1,
    ...dataSample.map(r => (r ? r.length : 0)),
  );

  /** Trailing user cols sau last bank header (MB 9+). Payroll Note đã map qua noteHeaderIdx. */
  const trailingNoteIdxs: number[] = [];
  for (let c = lastBankHeaderCol + 1; c < maxCols; c++) {
    if (c === noteHeaderIdx) continue;
    let nonEmpty = 0;
    for (const r of dataSample) {
      if (String(r?.[c] ?? '').trim()) nonEmpty += 1;
    }
    if (nonEmpty > 0) trailingNoteIdxs.push(c);
  }

  const lines: BatchDetailLine[] = [];
  for (let i = headerRowIndex + 1; i < rawRows.length; i++) {
    const row = rawRows[i] as unknown[];
    if (!row || row.every(c => String(c).trim() === '')) continue;

    if (sttIdx >= 0) {
      const stt = String(row[sttIdx] ?? '').trim();
      if (stt && !/^\d+$/.test(stt)) continue;
    }

    const name = nameIdx >= 0 ? String(row[nameIdx] ?? '').trim() : '';
    if (!name || /^t\u1ed5ng/i.test(name) || /^total/i.test(name)) continue;

    const amount = amtIdx >= 0 ? parseBatchAmount(row[amtIdx]) : 0;
    const statusRaw = statusIdx >= 0 ? String(row[statusIdx] ?? '').trim() || undefined : undefined;
    const ftCell = (guessedFtIdx >= 0 ? String(row[guessedFtIdx] ?? '') : '').trim();
    const success = isBatchLineSuccess(statusRaw);

    let ftNumber: string | undefined;
    let errorReason: string | undefined;
    if (ftCell) {
      if (looksLikeFt(ftCell)) {
        ftNumber = ftCell;
      } else if (!success) {
        // MB TB: «Bút toán/Lý do» = message lỗi
        errorReason = ftCell;
      } else {
        ftNumber = ftCell;
      }
    }

    // staffNote: cột Note trong header (Payroll) · else trailing · join nếu nhiều
    const noteParts: string[] = [];
    if (noteHeaderIdx >= 0) {
      const n = String(row[noteHeaderIdx] ?? '').trim();
      if (n) noteParts.push(n);
    }
    for (const c of trailingNoteIdxs) {
      const n = String(row[c] ?? '').trim();
      if (n) noteParts.push(n);
    }
    const staffNote = noteParts.length ? noteParts.join(' · ') : undefined;
    const companyCode = staffNote && /^[A-Za-z0-9._-]{2,16}$/.test(staffNote)
      ? staffNote.toUpperCase()
      : undefined;

    lines.push({
      lineIndex: lineOffset + (i - headerRowIndex - 1),
      beneficiaryName: name,
      accountNumber: accIdx >= 0 ? String(row[accIdx] ?? '').trim() || undefined : undefined,
      bankName: bankIdx >= 0 ? String(row[bankIdx] ?? '').trim() || undefined : undefined,
      amount,
      description: descIdx >= 0 ? String(row[descIdx] ?? '').trim() || undefined : undefined,
      status: statusRaw,
      ftNumber,
      errorReason,
      sheetDate: meta.transactionDate,
      batchRef: meta.refNumber,
      staffNote,
      companyCode,
      sourcePath: sourceFilePath
        ? formatBatchSourcePath(sourceFilePath, sheetTabName, i + 1)
        : undefined,
    });
  }
  return lines;
}

function getFileRelativePath(file: File): string {
  const withPath = file as File & { webkitRelativePath?: string };
  const rel = withPath.webkitRelativePath?.trim();
  return (rel || file.name).replace(/\\/g, '/');
}

/** Parse 1 file lô (xlsx/xls/csv) — multi-sheet. */
export async function parseBatchPaymentFile(file: File): Promise<BatchDetailLine[]> {
  try {
    const buffer = await file.arrayBuffer();
    const allLines: BatchDetailLine[] = [];
    const sourceFilePath = getFileRelativePath(file);

    if (file.name.toLowerCase().endsWith('.csv')) {
      const text = new TextDecoder('utf-8').decode(buffer);
      const rawRows = text.split('\n').filter(Boolean).map(l =>
        l.split(/[,;\t]/).map(c => c.trim()),
      ) as unknown[][];
      const meta = extractBatchSheetMeta(rawRows);
      allLines.push(...parseBatchSheet(rawRows, meta, 0, sourceFilePath, 'csv'));
    } else {
      const wb = XLSX.read(buffer, { type: 'array' });
      let lineOffset = 0;
      for (const sheetName of wb.SheetNames) {
        const sheet = wb.Sheets[sheetName];
        const rawRows: unknown[][] = XLSX.utils.sheet_to_json<unknown[]>(sheet, { header: 1, defval: '' });
        const meta = extractBatchSheetMeta(rawRows);
        const sheetLines = parseBatchSheet(rawRows, meta, lineOffset, sourceFilePath, sheetName);
        allLines.push(...sheetLines);
        lineOffset += sheetLines.length;
      }
    }
    return allLines;
  } catch {
    return [];
  }
}

/** Map batchRef → lines (dùng đối soát / dry-run). */
export async function parseBatchPaymentFilesToMap(
  files: File[],
): Promise<Map<string, BatchDetailLine[]>> {
  const result = new Map<string, BatchDetailLine[]>();
  await Promise.all(
    files.map(async (file) => {
      const lines = await parseBatchPaymentFile(file);
      for (const line of lines) {
        const ref = line.batchRef || file.name;
        if (!result.has(ref)) result.set(ref, []);
        result.get(ref)!.push(line);
      }
    }),
  );
  return result;
}
